    for idx, item in enumerate(raw_data):
        row = item.copy()
        
        # Non-null / default values for columns if missing
        if "STARTTIME" not in row:
            row["STARTTIME"] = None
        if "ENDTIME" not in row:
            row["ENDTIME"] = None
        if "ISACTIVE" not in row:
            row["ISACTIVE"] = 1
        if "EXECUTIONORDER" not in row:
            row["EXECUTIONORDER"] = idx
        if "BUSINESSUNITID" not in row:
            row["BUSINESSUNITID"] = -1
        if "ASSIGNMENTONLYLOGGEDINUSER" not in row:
            row["ASSIGNMENTONLYLOGGEDINUSER"] = 0
        if "UNIQUEID" not in row:
            # Generate UUID from namespace/seed or random for realism
            # Let's seed using queue name to be reproducible
            seed_uuid = str(uuid.uuid5(uuid.NAMESPACE_DNS, row["NAME"])).upper()
            # Mutate slightly to look like "07..."
            row["UNIQUEID"] = "07" + seed_uuid[2:]
        if "LASTMODIFIEDBYTYPE" not in row:
            # Let's set it logically based on default owner id
            row["LASTMODIFIEDBYTYPE"] = 0 if row.get("LASTMODIFIEDBY", 1) > 1 else -1
        if "STARTMIN" not in row:
            row["STARTMIN"] = 0
        if "ENDMIN" not in row:
            row["ENDMIN"] = 0
        if "QUEUECRITERIA" not in row:
            row["QUEUECRITERIA"] = "0<expr..."
